```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a new string to hold the HTML output
    std::string html;

    // Create a new string stream to read the markdown text
    std::stringstream ss(markdown);

    // Read the markdown text
    std::string line;
    while (ss >> line) {
        // Convert each line to HTML
        html += "<p>" + line + "</p>";
    }

    // Return the HTML output
    return html;
}

int main() {
    std::string markdown = "# Hello, World!\n\nThis is a test line.\n\nAnother line.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

